using OrbitalSentinel.Core;
using OrbitalSentinel.Propagation;

namespace OrbitalSentinel.UnitTests;

public sealed class Sgp4OrbitPropagatorTests
{
    private readonly Sgp4OrbitPropagator _propagator = new();

    [Theory]
    // Published independent WGS72 reference, not generated by this adapter.
    // https://celestrak.org/publications/AIAA/2006-6753/ (tcppver.out, satellite 5).
    // SGP.NET uses WGS84; explicit 100 m / 0.1 m/s tolerances accommodate that model difference.
    [InlineData(0, 7022.46529266, -1400.08296755, 0.03995155, 1.893841015, 6.405893759, 4.534807250)]
    [InlineData(360, -7154.03120202, -3783.17682504, -3536.19412294, 4.741887409, -4.151817765, -2.093935425)]
    public void PropagationAgreesWithValladoReferenceWithinDocumentedModelTolerance(
        int minutes, double x, double y, double z, double vx, double vy, double vz)
    {
        var orbit = ReferenceOrbit.Snapshot();
        var state = _propagator.Propagate(orbit, orbit.Elements.EpochUtc.AddMinutes(minutes));
        AssertVectorClose(new CartesianVector(x, y, z), state.PositionKm, 0.1);
        AssertVectorClose(new CartesianVector(vx, vy, vz), state.VelocityKmPerSecond, 0.0001);
    }

    [Fact]
    public void PropagationPreservesPrecisionBeyondTleAngleFormatting()
    {
        var original = ReferenceOrbit.Snapshot();
        var modified = ReferenceOrbit.Snapshot(original.Elements with
        {
            MeanAnomalyDegrees = original.Elements.MeanAnomalyDegrees + 0.000001
        });
        var timestamp = original.Elements.EpochUtc;
        var before = _propagator.Propagate(original, timestamp);
        var after = _propagator.Propagate(modified, timestamp);
        var difference = Distance(before.PositionKm, after.PositionKm);
        Assert.InRange(difference, 0.000001, 0.01);
    }

    [Fact]
    public void ExternalCatalogIdDoesNotAffectPropagation()
    {
        var orbit = ReferenceOrbit.Snapshot();
        var withoutId = _propagator.Propagate(orbit, orbit.Elements.EpochUtc);
        var withLargeId = _propagator.Propagate(orbit with
        {
            Object = orbit.Object with { NoradCatalogId = long.MaxValue }
        }, orbit.Elements.EpochUtc);
        Assert.Equal(withoutId, withLargeId);
    }

    [Fact]
    public void DefaultPredictionIncludesBothEndpointsAndHas1441Points()
    {
        var orbit = ReferenceOrbit.Snapshot();
        var result = _propagator.Predict(orbit, orbit.Elements.EpochUtc,
            TimeSpan.FromHours(24), TimeSpan.FromSeconds(60), CancellationToken.None);
        Assert.Equal(1441, result.Points.Count);
        Assert.Equal(orbit.Object.Id, result.OrbitalObjectId);
        Assert.Equal(orbit.Version, result.OrbitVersion);
        Assert.Equal(result.StartUtc, result.Points[0].TimestampUtc);
        Assert.Equal(result.EndUtc, result.Points[^1].TimestampUtc);
        Assert.All(result.Points, point => Assert.True(double.IsFinite(point.PositionEcefMeters.X)));
    }

    [Fact]
    public void NonDivisibleHorizonIncludesExactFinalTimestampWithoutOvershooting()
    {
        var orbit = ReferenceOrbit.Snapshot();
        var result = _propagator.Predict(orbit, orbit.Elements.EpochUtc,
            TimeSpan.FromSeconds(125), TimeSpan.FromSeconds(60), CancellationToken.None);
        Assert.Equal(new[] { 0d, 60d, 120d, 125d }, result.Points.Select(point =>
            (point.TimestampUtc - result.StartUtc).TotalSeconds));
    }

    [Theory]
    [InlineData(0, 60)]
    [InlineData(172801, 60)]
    [InlineData(86400, 0)]
    [InlineData(86400, -1)]
    [InlineData(86400, 0.5)]
    [InlineData(86400, 1)]
    [InlineData(60, 61)]
    public void PredictionRejectsUnboundedOrInvalidSampling(double horizonSeconds, double stepSeconds)
    {
        var orbit = ReferenceOrbit.Snapshot();
        Assert.Throws<ArgumentOutOfRangeException>(() => _propagator.Predict(orbit, orbit.Elements.EpochUtc,
            TimeSpan.FromSeconds(horizonSeconds), TimeSpan.FromSeconds(stepSeconds), CancellationToken.None));
    }

    [Fact]
    public void PredictionHonorsCancellationBeforePropagation()
    {
        var orbit = ReferenceOrbit.Snapshot();
        Assert.Throws<OperationCanceledException>(() => _propagator.Predict(orbit, orbit.Elements.EpochUtc,
            TimeSpan.FromHours(24), TimeSpan.FromSeconds(60), new CancellationToken(true)));
    }

    [Fact]
    public void InvalidDeserializedElementsCannotReachTheLibrary()
    {
        var orbit = ReferenceOrbit.Snapshot();
        Assert.Throws<ArgumentOutOfRangeException>(() => _propagator.Propagate(
            orbit with { Elements = orbit.Elements with { MeanMotionRevolutionsPerDay = double.NaN } },
            orbit.Elements.EpochUtc));
    }

    private static void AssertVectorClose(CartesianVector expected, CartesianVector actual, double tolerance) =>
        Assert.InRange(Distance(expected, actual), 0, tolerance);

    private static double Distance(CartesianVector a, CartesianVector b) => Math.Sqrt(
        Math.Pow(a.X - b.X, 2) + Math.Pow(a.Y - b.Y, 2) + Math.Pow(a.Z - b.Z, 2));
}
